{title:"Hear It From Creators, Brands and Agencies",subtitle:"See how creators, businesses, and agencies use BOOSTDZ for real social proof and measurable social media growth.",likesDelivered:"Likes delivered this month",satisfaction:"Customer satisfaction rate",leaveReviewTitle:"Love BOOSTDZ? Leave a review",leaveReviewBody:"Tell other creators what worked for you. Your review helps the community pick the right tools.",leaveReviewCta:"Leave a Review",tapToPlay:"Tap to play · swipe for more",items:[{quote:"I was skeptical at first, but BOOSTDZ delivered exactly what they promised. My Instagram posts went from 50 likes to over 500 in a week, and the followers are real accounts — I checked. Game changer for my small business.",name:"John Mitchell",role:"Founder @ Northbay Goods",avatar:"/assets/testimonials/1.webp"},{quote:"Got my first 1k followers in days. Real ones. BOOSTDZ made posting feel good again — engagement that actually sticks.",name:"Sarah Chen",role:"Content Creator",avatar:"/assets/testimonials/2.webp"},{quote:"We run 12 client accounts. BOOSTDZ is the only panel that delivers consistently without drop-offs. Our agency workflow depends on it.",name:"Marcus Webb",role:"Agency Director",avatar:"/assets/testimonials/3.webp"},{quote:"TikTok views landed within minutes. My FYP reach doubled in two weeks. Best investment for a new creator.",name:"Elena Rodriguez",role:"TikTok Creator",avatar:"/assets/testimonials/4.webp"},{quote:"Support answered in under 5 minutes when I had a question. That alone makes BOOSTDZ worth it for our brand team.",name:"David Park",role:"Brand Manager",avatar:"/assets/testimonials/5.webp"}]},OE=[{label:"Products",href:"#platforms"},{label:"Why",href:"#why"}],RE=[{n:"1",title:"Choose",body:"Browse our catalog and pick the perfect package for your Instagram, TikTok, or Twitter account."},{n:"2",title:"Order",body:"Paste your profile or post link, select a quantity, and complete your order in seconds."},{n:"3",title:"Grow",body:"Delivery starts within minutes — real likes, followers, and views, drip-fed for natural-looking growth."}],BE={links:[{label:"Sign In",href:"#"},{label:"Sign Up",href:"#"},{label:"Reviews",href:"#testimonials"},{label:"Contact",href:"#"},{label:"API Docs",href:"#"},{label:"Blog & News",href:"#"},{label:"Who It's For",href:"#"},{label:"Brand Assets",href:"#"}],products:["Buy TikTok Likes","Buy Twitter Likes","Buy YouTube Likes","Buy YouTube Views","Buy Instagram Likes","Buy Instagram Views","Buy TikTok Followers","Buy TikTok Views","Buy Twitter Followers","Buy Instagram Comments","Buy Instagram Followers","Buy YouTube Subscribers"],tools:["Free TikTok Counter","Free Instagram Likes","Free AI Hashtag Generator","Free TikTok Likes Counter","Free Instagram Story Viewer","Free TikTok Money Calculator","Free TikTok Video Downloader","Free Instagram Followers Counter","Free TikTok Engagement Rate Calculator","Free YouTube Views"],comparisons:["Twicsy Alternative","Buzzoid Alternative","Famoid Alternative","Likes.io Alternative","Media Mister Alternative","Best Sites: Instagram Followers","Best Sites: Instagram Likes","Best Sites: TikTok Followers","Best Sites: TikTok Views"],sections:{links:"Links",products:"Featured Products",tools:"Free Tools",comparisons:"Comparisons"},about:"Powering social media growth. BOOSTDZ serves creators, agencies, and brands with engagement services across Instagram, TikTok, YouTube, and X. Based in Algeria.",rights:"All rights reserved.",terms:"Terms of Service",refund:"Refund Policy",privacy:"Privacy Policy"},_E={brand:HE,header:CE,hero:FE,preview:TE,why:AE,platforms:DE,testimonials:LE,nav:OE,steps:RE,footer:BE},VE=[{group:"General",items:[{q:"What is BOOSTDZ?",a:"BOOSTDZ helps influencers, brands, agencies and business owners grow their social presence. We serve creators and professionals with likes, followers, and views across Instagram, TikTok, YouTube, X, Threads, and Facebook."},{q:"Do I need to give any credentials to get started?",a:"Nope. No usernames or passwords needed. Drop us your profile or post link and we handle the rest. There is one special case for Facebook where you may need to approve an ad account."},{q:"Why we are different?",a:"BOOSTDZ focuses on premium quality delivery, a tailored experience for professionals and agencies, and support that actually replies. Pricing matters — service and retention matter more."}]},{group:"Orders & Services",items:[{q:"Is buying likes and followers safe?",a:"Our services are designed to be low-risk for your account. Many deliveries run through ads and influencer marketing, which are common practices in the industry."},{q:"What is drip-feed delivery and why does it matter?",a:"Drip-feed spreads your order over hours or days instead of dumping it all at once. That keeps growth looking natural, protects your account from sudden spikes, and helps engagement stick."},{q:"How does the automatic refill guarantee work?",a:"If likes, followers, or views drop after delivery, our system tops your order back up at no extra cost for the package retention window — no support ticket needed in most cases."},{q:"Can I track my orders in real time?",a:"Yes. Every order shows live progress in your dashboard with start time, current count, and estimated completion."},{q:"My order is stuck, slow, or not delivered!",a:"Orders can stall from time to time. Our system retries automatically — please give it some time. If it persists, contact us and we will look into it."},{q:"I'm not satisfied with the quality, what should I do?",a:"Quality can vary across providers. If it happens, contact us and we will look into it right away."}]},{group:"Payments",items:[{q:"What payment methods do you accept?",a:"We accept major credit cards, bank transfers, digital wallets, and cryptocurrencies. Business customers can request invoicing with proper documentation."},{q:"What is your refund policy?",a:"If your order is not delivered you are eligible for a credit refund to your account. Purchased credits are generally non-refundable — deposit only what you need. See our Refund Policy for details."},{q:"Can you send me an invoice?",a:"Yes — contact support with your company name, address, and VAT number if applicable. Invoices are usually processed within 24–48h."}]}],qE={groups:VE},$E="Solde",UE="Fermer",GE="Fermer la fenêtre",YE="par 1K",PE="{{count}} unités",KE="Tout voir",ZE="Chargement…",QE="Utilisateur",XE="—",IE="DA",JE="La requête a échoué.",WE="Nouvelle commande",ew="Annuler",tw="Confirmer",lw="Retour",aw={label:"Langue",en:"Anglais",fr:"Français",ar:"Arabe"},nw={toggleTheme:"Changer le thème",signOut:"Se déconnecter",closeMenu:"Fermer le menu",openMenu:"Ouvrir le menu",sidebar:"Barre latérale",hidePassword:"Masquer le mot de passe",showPassword:"Afficher le mot de passe"},rw={completed:"Terminé",processing:"En traitement",inProgress:"En cours",pending:"En attente",partial:"Partiel",canceled:"Annulé",refunded:"Remboursé",failed:"Échoué",rejected:"Rejeté",approved:"Terminé"},iw={service:"Service",order:"Commande",status:"Statut",progress:"Progression",amount:"Montant",reference:"Référence",method:"Méthode",date:"Date",category:"Catégorie",min:"Min",max:"Max",pricePer1k:"Prix / 1K",startingAt:"À partir de",action:"Action",delivery:"Livraison"},sw={balance:$E,close:UE,closeDialog:GE,per1k:YE,units:PE,seeAll:KE,loading:ZE,userFallback:QE,emDash:XE,currency:IE,requestFailed:JE,newOrder:WE,cancel:ew,confirm:tw,back:lw,language:aw,aria:nw,status:rw,table:iw},ow="Tableau de bord",cw="Commandes",uw="Créer une commande",dw="Historique des commandes",mw="Commandes répétées",hw="Gérez le rechargement automatique et les boosts récurrents pour les publications qui nécessitent un engagement continu.",fw="Paiement",pw="CCP / BaridiMob",gw="Tarifs",vw="Facturation",xw="FAQ et aide",yw={dashboard:ow,orders:cw,createOrder:uw,orderHistory:dw,repeatedOrders:mw,repeatedOrdersDescription:hw,checkout:fw,ccpBaridimob:pw,pricing:gw,billing:vw,faqsHelp:xw},bw="Bon retour",E